-- The per-type channel preference matrix: one row per recipient and type, holding
-- the channels that recipient selected for that type. A recipient a type has no
-- row for takes the type's default channels, and a type that cannot be
-- unsubscribed has no row here at all.
--
-- The tenant column leads the key, as it does on every scoped table: the model
-- embeds tenant.Model, and the key the convention declares is the key the table
-- must declare. The identifier is generated by the module, not by the database,
-- so the key is the tenant column and the identifier together.
--
-- The channels are a stable-sorted JSON array kept as text: the order of the set
-- is part of the value and nothing queries a channel by its part, so the column
-- is opaque to the statement path and is decoded into a channel set on read.
CREATE TABLE IF NOT EXISTS notification_preferences (
    id                TEXT        NOT NULL,
    tenant_id         TEXT        NOT NULL,
    recipient_user_id TEXT        NOT NULL,
    type_key          TEXT        NOT NULL,
    channels          TEXT        NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL,
    updated_at        TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (tenant_id, id)
);

-- One recipient has at most one row per type. The upsert that lands a preference
-- converges on this index, so two concurrent writes of one key leave one row.
CREATE UNIQUE INDEX IF NOT EXISTS notification_preferences_recipient_type_idx
    ON notification_preferences (tenant_id, recipient_user_id, type_key);
